package dev.hexora.controller;
import dev.hexora.dto.request.ProjectRequest; import dev.hexora.dto.response.*; import dev.hexora.enums.ProjectStatus; import dev.hexora.service.ProjectService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.data.domain.*; import java.util.*;
@RestController @RequestMapping("/api/projects") public class ProjectController {private final ProjectService s;public ProjectController(ProjectService s){this.s=s;} @GetMapping("/public") ApiResponse<?> pub(){return ApiResponse.success(s.all(Sort.by("projectDate").descending()));} @GetMapping("/public/{slug}") ApiResponse<?> slug(@PathVariable String slug){return ApiResponse.success(s.findBySlug(slug));} @GetMapping("/public/status/{status}") ApiResponse<?> status(@PathVariable String status){return ApiResponse.success(s.byStatus(ProjectStatus.fromString(status)));} @GetMapping("/public/recent") ApiResponse<?> recent(@RequestParam(defaultValue="6")int limit){return ApiResponse.success(s.all(PageRequest.of(0,Math.min(Math.max(limit,1),50),Sort.by("projectDate").descending())).getContent());} @GetMapping("/public/stats") ApiResponse<?> stats(){return ApiResponse.success(Map.of("total",s.count(),"completed",s.countByStatus(ProjectStatus.COMPLETED),"inProgress",s.countByStatus(ProjectStatus.IN_PROGRESS)));} @PostMapping ApiResponse<?> create(@Valid @RequestBody ProjectRequest r){return ApiResponse.created(s.create(r));} @PutMapping("/{id}") ApiResponse<?> update(@PathVariable Long id,@Valid @RequestBody ProjectRequest r){return ApiResponse.success(s.update(id,r));} @DeleteMapping("/{id}") ResponseEntity<?> del(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}}
